*******************************************************************			 ******	       Install		 ******	     Version 5.1		 ******	   March 3, 1989		 ******			 ******			 ******  This is the install routine for the patch to ROM 3.	 ******			 **************************************************************************************************************************************			 ******			 ******            Copyright (C) Apple Computer, Inc.	 ******            1985-1989		 ******            All Rights Reserved		 ******			 ******			 ********************************************************************* 5/11/89	Mensch** Code stolen from ts2 patch. Modified for ts3 patch Installed * the first patch that being the window manager stuff.** 16 May 89	Steven Glass** Added patch to menu manager.** 18 May 89	Steven Glass** Added patch to list manager.** 11/16/89	Mensch* Added Event manager patch.** 23 Jan 90	Yee* Remove Event manager patch.** 2/22/90	mensch* add misc tools patch for the first time** 17-Sep-90	Dave Lyons** Removed dependency on all.macros.* Added Tool Locator patch.** 24-Sep-90	Dave Lyons** Added Scrap Manager patch.* Replaced the series of SetTSPtr calls with a loop and a* table.  This saves space.** 23-Oct-90	Dave Lyons** Added Event Manager to patch table.** 14-Nov-90	Dave Lyons** Added JSL AddTBNotifyProc.  Put back all.macros.** 4-Dec-90	Dave Lyons** Kill List Manager patch.** 6-Jan-91	Dave Lyons** For now, we're killing the ROM Font Manager in favor of* TOOL027.  Probably I'll patch it later.** 14-Jan-91	Dave Lyons** For now, we're also killing the Scrap Manager in favor of* TOOL022.  Will almost certainly bring it back later (there's* a Close(0) bug in the ROM--can probably work around).** 10-Mar-91	Dave Lyons** Added FixSysBeep routine--I need to patch the bell vector now* to support "give visual indication of sounds" bit in BRAM.** 11-Mar-91	Dave Lyons** Killed Line Edit in the patch table.  I'll put some of it* back later, but for now we're using Tool020.** 16-Apr-91	Dave Lyons** Added call to AddTBRequestHandler (in Locator.pch).** 17-Sep-91	Dave Lyons** Moved AddTBNotifyProc and AddTBRequestProc to Tool.Setup.** 5-Nov-91	Dave Lyons** Now patches Text Tools (added one line in PatchTable).******************************************************************* Begin 6.0.1** 5-Mar-92	Dave Lyons (6.0.1d_)** Patch Integer Math.** 24-Mar-93	Dave Lyons (6.0.1d15)** So that we can use the disk-based scrap later, undo what* the ROM-based ScrapBootInit did (dispose all $4201 memory* and set the Scrap Manager's WAP to NIL).** 6-May-93 	Jim Murphy (6.0.1 final)** Added SANE to patch table.*****************************************************************	blanks off	string asis	datachk off	include 'all.macros'	include ':::sys.equs.asm'	import LocatorCallTable	import SoundCallTable	Import WMCallTable	import MenuCallTable*	import ListCallTable	;removed 4-Dec-90 DAL	import InstallQDPatch	import FMCallTable	import DialogCallTable	import ControlCallTable	import DeskCallTable	import LECallTable	import MMCallTable	import MTCallTable	import ScrapCallTable	import EMCallTable	entry FixSysBeep		;10-Mar-91 DAL	import AddTBNotifyProc	import AddTBRequestHandler	;16-Apr-91 DAL	import TTCallTable		;5-Nov-91 DAL	import IMCallTable		;5-Mar-92 DAL	import Sane2CallTable	;6-May-93 JCMInstall	PROC;---------------------------------------------------;; Install the QD Patch (This one is special);	jsl InstallQDPatch** Do a bunch of SetTSPtrs from a table** New routine 24-Sep-90 DAL*	phb	phk	plb	ldx #0	;index into table@patch1tool	lda PatchTable+2,x	;flag word	bmi @done	phx	;keep index into table	pha	;push flag word	lda PatchTable,x	pha	;push toolset number	lda PatchTable+6,x	pha	;push high word of FPT	lda PatchTable+4,x	pha	;push low word of FPT	_SetTSPtr	pla	;retrieve index	clc	adc #8	tax	bra @patch1tool@done	plb	jsl FixSysBeep*** added 24-Mar-93 DAL -- undo the nasty effects of the ROM-based ScrapBootInit	lda #0	pha	;System tool flag	pea $0016	;Scrap Manager tool number	pha	pha	;NIL	_SetWAP	pea $4201	;Scrap Manager's ID	_DisposeAll*** end 24-Mar-93;; Now unload this segment of code be sure to do a jump instead; of a jsl this way we don't have to worry about whether this code; disappears...;	pha	; DAL 18-Sep-90	_MMStartUp	; DAL 18-Sep-90	plx	; DAL 18-Sep-90	longa off	sep #$20	pla	ply	; get the return address from the stack*** Our ID isn't necessarily A002.  DAL 17-Sep-90***	pea $A002	phx	; DAL 18-Sep-90	pea $0001	; and our file num...	pea $0001	; even our segment number...	phy	pha	; put the return address back...	longa On	rep #$20	ldx #$0C11	; and make the UnloadsegNumCall	jml >$E10000	; and call the tool locator...********************************************************************************** PatchTable** For each toolset to be patched, we have two Longs:**	dc.l $000x00tt,xxxCallTable** x is 1 if we need to do a "special" patch (tool 1 or 5 on ROM 3)* tt is the toolset number toopatch* xxxCallTable is the new call table**********************************************************************************PatchTable	dc.l $00010001,LocatorCallTable	;Tool Locator (17-Sep-90 DAL)	dc.l $00000002,MMCallTable	;Memory Manager	dc.l $00000003,MTCallTable	;Misc Tools	dc.l $00010005,DeskCallTable	;Desk Manager	dc.l $00000006,EMCallTable	;Event Manager (23-Oct-90 DAL)	dc.l $00000008,SoundCallTable	;Sound Tools	dc.l $0000000A,Sane2CallTable	;SANE Tools (6-May-93 JCM)	dc.l $0000000B,IMCallTable	;Integer Math (5-Mar-92 DAL for 6.1d2)	dc.l $0000000C,TTCallTable	;Text Tools (5-Nov-91 DAL)	dc.l $0000000E,WMCallTable	;Window Manager	dc.l $0000000F,MenuCallTable	;Menu Manager	dc.l $00000010,ControlCallTable	;Control Manager*	dc.l $00000014,LECallTable	;Line Edit	dc.l $00000014,$FE0265	;USE TOOL020 for now (11-Mar-91 DAL)	dc.l $00000015,DialogCallTable	;Dialog Manager*	dc.l $00000016,ScrapCallTable	;Scrap manager (24-Sep-90 DAL)	dc.l $00000016,$FE0265	;Use RAM-based scrap mgr, 14-Jan-91 DAL*	dc.l $0000001B,FMCallTable	;Font Manager	dc.l $0000001B,$FE0265	;Font Manager DISABLED for now (6-Jan-91 DAL)*	dc.l $0000001C,ListCallTable	;List Manager (removed 4-Dec-90 DAL)	dc.l $0000001C,$FE0265	;List Manager (empty!) (4-Dec-90 DAL)	dc.l $ffffffff	EndP******************************************************************* FixSysBeep.** This routine copies the current contents of the* sysbeep vector to	a location below and substitues the a* address of NewSysBeep.******************************************************************FixSysBeep	PROC Export	import NewSysBeep	Import OrigBellVector		lda >BellVector	sta >OrigBellVector	lda >BellVector+2	sta >OrigBellVector+2	lda #NewSysBeep	sta >BellVector+1	lda #>NewSysBeep	sta >BellVector+2	rtl	EndP	END